int main() {
    string s;
    getline(cin , s);
    // 统计每个字母首次出现的位置
    vector<string> tmp = split(s, " ");
    string input = tmp[0];
    int k = stoi(tmp[1]);
    int n = input.size();
    map<char, int> mp;
    // 输入存在异常
    if (k > n) {
        cout << -1;
        return 0;
    }
    for (int i = 0; i < n; i++) {
        char c = s[i];
        if (mp.find(c) == mp.end()) {
            mp[c] = i;
        }
    }
​
    sort(input.begin(), input.end());
    // 1-base 转换为 0- base
    cout << mp[input[k-1]];
    return 0;
}
