package main
​
import (
    "bufio"
    "fmt"
    "os"
    "sort"
    "strconv"
    "strings"
)
​
func main() {
    reader := bufio.NewReader(os.Stdin)
    line, _ := reader.ReadString('\n')
    line = strings.TrimSpace(line)
​
    // 拆分字符串和数字
    parts := strings.Split(line, " ")
    input := parts[0]
    k, _ := strconv.Atoi(parts[1])
    n := len(input)
​
    // 输入存在异常
    if k > n {
        fmt.Println(-1)
        return
    }
​
    // 统计每个字母首次出现的位置
    mp := make(map[byte]int)
    for i := 0; i < n; i++ {
        c := input[i]
        if _, ok := mp[c]; !ok {
            mp[c] = i
        }
    }
​
    // 排序字符串
    chars := []byte(input)
    sort.Slice(chars, func(i, j int) bool {
        return chars[i] < chars[j]
    })
​
    // 1-base 转换为 0-base
    fmt.Println(mp[chars[k-1]])
}
